    <style>
      :root {
        color-scheme: dark;
        --bg: #0c111d;
        --surface: #151b2c;
        --surface-strong: #1d263b;
        --text: #f6f8ff;
        --muted: #c5cee3;
        --accent: #8fb4ff;
        --accent-strong: #a8c5ff;
        --border: #3a4664;
        --shadow: #05070d;
      }

      * {
        box-sizing: border-box;
      }

      html {
        min-width: 320px;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        line-height: 1.5;
        color: var(--text);
        background:
          radial-gradient(circle at top left, #20395f 0, transparent 32rem),
          linear-gradient(135deg, #080c15 0%, var(--bg) 55%, #111827 100%);
      }

      .skip-link {
        position: absolute;
        top: 0.75rem;
        left: 0.75rem;
        z-index: 10;
        padding: 0.625rem 0.875rem;
        color: #08111f;
        background: var(--accent-strong);
        border-radius: 999px;
        transform: translateY(-150%);
      }

      .skip-link:focus {
        transform: translateY(0);
        outline: 3px solid transparent;
        box-shadow: 0 0 0 4px #0c111d, 0 0 0 7px var(--accent-strong);
      }

      .page-shell {
        display: grid;
        min-height: 100vh;
        place-items: center;
        padding: 2rem 1rem;
      }

      .card {
        width: min(100%, 30rem);
        padding: clamp(1.5rem, 5vw, 2.25rem);
        background: linear-gradient(180deg, var(--surface) 0%, #101625 100%);
        border: 1px solid var(--border);
        border-radius: 1.5rem;
        box-shadow: 0 1.5rem 3.5rem var(--shadow);
      }

      h1 {
        margin: 0 0 0.625rem;
        font-size: clamp(1.75rem, 8vw, 2.5rem);
        line-height: 1.1;
        letter-spacing: -0.04em;
      }

      .lede {
        margin: 0 0 1.75rem;
        color: var(--muted);
      }

      form {
        display: grid;
        gap: 1.25rem;
      }

      .form-field {
        display: grid;
        gap: 0.625rem;
        padding: 1rem;
        background: var(--surface-strong);
        border: 1px solid var(--border);
        border-radius: 1rem;
      }

      .checkbox-row {
        display: flex;
        align-items: flex-start;
        gap: 0.75rem;
      }

      input[type="checkbox"] {
        width: 1.25rem;
        height: 1.25rem;
        margin: 0.125rem 0 0;
        accent-color: var(--accent);
        flex: 0 0 auto;
      }

      input[type="checkbox"]:focus-visible,
      button:focus-visible {
        outline: 3px solid transparent;
        box-shadow: 0 0 0 4px #0c111d, 0 0 0 7px var(--accent-strong);
      }

      label {
        font-weight: 700;
        color: var(--text);
        overflow-wrap: anywhere;
      }

      .required {
        font-weight: 800;
      }

      .helper-text {
        margin: 0 0 0 2rem;
        color: var(--muted);
        font-size: 0.95rem;
        overflow-wrap: anywhere;
      }

      button {
        width: 100%;
        min-height: 3rem;
        padding: 0.875rem 1.125rem;
        color: #07101f;
        font: inherit;
        font-weight: 800;
        background: linear-gradient(135deg, var(--accent-strong), #d2e0ff);
        border: 1px solid #d6e2ff;
        border-radius: 999px;
        cursor: pointer;
      }

      button:hover {
        background: linear-gradient(135deg, #bed3ff, #eef4ff);
      }

      button:active {
        transform: translateY(1px);
      }

      @media (max-width: 22rem) {
        .helper-text {
          margin-left: 0;
        }
      }

      @media (forced-colors: active) {
        body,
        .card,
        .form-field {
          color: CanvasText;
          background: Canvas;
          border-color: ButtonBorder;
          box-shadow: none;
        }

        .skip-link,
        button {
          color: ButtonText;
          background: ButtonFace;
          border-color: ButtonBorder;
        }

        .lede,
        .helper-text {
          color: CanvasText;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content" class="page-shell">
      <div id="root"></div>
    </main>

    <script>
      const h = (tag, props = {}, ...children) => {
        const node = document.createElement(tag);

        Object.entries(props).forEach(([key, value]) => {
          if (key === "className") {
            node.className = value;
          } else if (key === "htmlFor") {
            node.htmlFor = value;
          } else if (key.startsWith("on") && typeof value === "function") {
            node.addEventListener(key.slice(2).toLowerCase(), value);
          } else if (typeof value === "boolean") {
            if (value) node.setAttribute(key, "");
          } else {
            node.setAttribute(key, value);
          }
        });

        children.flat().forEach((child) => {
          node.append(
            child instanceof Node ? child : document.createTextNode(String(child))
          );
        });

        return node;
      };

      function ConsentField() {
        const checkboxId = "terms-consent";
        const helperId = "terms-consent-help";

        return h(
          "div",
          { className: "form-field" },
          h(
            "div",
            { className: "checkbox-row" },
            h("input", {
              type: "checkbox",
              id: checkboxId,
              name: "termsConsent",
              required: true,
              "aria-describedby": helperId,
            }),
            h(
              "label",
              { htmlFor: checkboxId },
              "I agree to the terms of use ",
              h("span", { className: "required", "aria-hidden": "true" }, "*")
            )
          ),
          h(
            "p",
            { id: helperId, className: "helper-text" },
            "Required to continue. Review the terms before submitting."
          )
        );
      }

      function ConsentForm() {
        return h(
          "form",
          {
            action: "#",
            method: "post",
            onSubmit: (event) => {
              event.preventDefault();
            },
          },
          ConsentField(),
          h("button", { type: "submit" }, "Submit agreement")
        );
      }

      function App() {
        return h(
          "section",
          { className: "card", "aria-labelledby": "page-title" },
          h("h1", { id: "page-title" }, "Terms agreement"),
          h(
            "p",
            { className: "lede" },
            "Confirm your consent to continue with your account setup."
          ),
          ConsentForm()
        );
      }

      document.getElementById("root").append(App());
    </script>
  </body>
</html>
